record.field:
# Log message to server output
log("Executing Send Custom VIP Email server action for order: %s" % record.name)

# Post tracking message to chatter
if record.partner_id and record.partner_id.x_is_vip_client:
    record.message_post(
        body="VIP Client Alert: Custom VIP notification processed for order %s." % record.name,
        subject="VIP Order Notification"
    )
else:
    record.message_post(
        body="Standard Client Notice: Custom notification processed for order %s." % record.name,
        subject="Order Notification"
    )
